    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))

    def find_root(parents):
        for i in range(n):
            if parents[i] == i + 1:
                return i + 1
        return None

    def make_valid(parents):
        visited = [False] * n
        changes = 0
        for i in range(n):
            current = i + 1
            path = []
            while current != -1 and not visited[current - 1]:
                visited[current - 1] = True
                path.append(current)
                next_node = parents[current - 1]
                if next_node == current:
                    break
                current = next_node
            else:
                continue
            if len(path) > 1:
                root = path[-1]
                for node in path[:-1]:
                    if parents[node - 1] != root:
                        parents[node - 1] = root
                        changes += 1
        return changes, parents

    root = find_root(a)
    if root is None:
        a[0] = 1
        root = 1

    for i in range(n):
        if a[i] == i + 1:
            continue
        current = a[i]
        visited = set()
        while current != root and current != i + 1 and current not in visited:
            visited.add(current)
            current = a[current - 1]
        if current == i + 1 or current in visited:
            a[i] = root

    changes, valid_a = make_valid(a)

    print(changes)
    print(" ".join(map(str, valid_a)))

